// Writes the list of app files and a content-hash version into app/sw.js and
// app/js/version.js. Run after changing anything in app/: npm run precache
// (`--check` exits non-zero when the generated files are out of date).
import { createHash } from 'node:crypto';
import { readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs';
import { dirname, join, relative, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const app = join(root, 'app');
const GENERATED = new Set(['sw.js', 'js/version.js']);
const EXCLUDED = /(^|\/)(\.|LICENSE$|.*\.LICENSE$)/;

function walk(dir) {
  return readdirSync(dir).flatMap((name) => {
    const path = join(dir, name);
    return statSync(path).isDirectory() ? walk(path) : [path];
  });
}

const files = walk(app)
  .map((path) => relative(app, path).split(sep).join('/'))
  .filter((path) => !GENERATED.has(path) && !EXCLUDED.test(path))
  .sort();

const hash = createHash('sha256');
for (const file of files) hash.update(file).update(readFileSync(join(app, file)));
const version = hash.digest('hex').slice(0, 10);

const swPath = join(app, 'sw.js');
const sw = readFileSync(swPath, 'utf8');
const block = `// <precache>\nconst VERSION = '${version}';\nconst FILES = [\n  './',\n` +
  `${[...files.filter((f) => f !== 'index.html'), 'js/version.js'].sort().map((f) => `  './${f}',`).join('\n')}\n];\n// </precache>`;
const nextSw = sw.replace(/\/\/ <precache>[\s\S]*?\/\/ <\/precache>/, block);
const versionPath = join(app, 'js', 'version.js');
const nextVersion = `// Generated by tools/gen-precache.mjs.\nexport const VERSION = '${version}';\n`;

if (process.argv.includes('--check')) {
  const current = (path) => { try { return readFileSync(path, 'utf8'); } catch { return ''; } };
  if (current(swPath) !== nextSw || current(versionPath) !== nextVersion) {
    console.error('app/sw.js or app/js/version.js is out of date: run npm run precache');
    process.exit(1);
  }
  console.log(`precache up to date (${version})`);
} else {
  writeFileSync(swPath, nextSw);
  writeFileSync(versionPath, nextVersion);
  console.log(`precache: ${files.length} files, version ${version}`);
}
